function dcSource(id,tags=[]){return{id,def:{tags:["dc",...tags]}}}
function dcStrongest(range=900){const p=game.player,a=game.enemies.filter(e=>!e.dead&&!e.isCaptive&&Math.hypot(e.x-p.x,e.y-p.y)<=range);a.sort((x,y)=>(Number(y.isBoss)-Number(x.isBoss))||(Number(y.isMiniBoss)-Number(x.isMiniBoss))||(Number(y.elite)-Number(x.elite))||y.hp-x.hp);return a[0]||null}
function dcLine(x1,y1,x2,y2,width,damage,source,color="#8eefff",opts={}){game.beams.push({x1,y1,x2,y2,life:opts.life||.13,color,width:Math.max(2,width*.38)});const cx=(x1+x2)/2,cy=(y1+y2)/2,r=Math.hypot(x2-x1,y2-y1)/2+width+45;for(const e of game.grid.queryCircle(cx,cy,r)){if(e.dead||e.isCaptive)continue;if(pointSegDist(e.x,e.y,x1,y1,x2,y2)<e.size+width){game.damageEnemy(e,damage,{source,canCrit:opts.canCrit!==false,damageType:opts.damageType||"arcane",knockback:opts.knockback||0,fromX:x1,fromY:y1,silent:!!opts.silent});if(opts.status)e.applyStatus(opts.status.type,opts.status.duration,opts.status.strength,source)}}}
function dcThreat(){const p=game.player,near=game.grid.queryCircle(p.x,p.y,620).filter(e=>!e.dead&&!e.isCaptive),boss=near.find(e=>e.isBoss||e.isMiniBoss),bullets=game.enemyProjectiles.filter(q=>!q.dead&&Math.hypot(q.x-p.x,q.y-p.y)<420).length;return{near,boss,bullets,swarm:near.length}}

class DCLassoEffect{
 constructor(w,s,target){this.weapon=w;this.s=s;this.target=target;this.life=this.max=s.duration;this.dead=false;this.tick=0}
 update(dt){this.life-=dt;this.tick-=dt;if(!this.target||this.target.dead){this.dead=true;return}const p=game.player,t=this.target,d=Math.hypot(t.x-p.x,t.y-p.y);if(!t.isBoss&&!t.isMiniBoss){const n=normalize(p.x-t.x,p.y-t.y),pull=Math.min(110,Math.max(0,d-85));t.x+=n.x*pull*dt*1.5*(1-t.knockbackResistance);t.y+=n.y*pull*dt*1.5*(1-t.knockbackResistance)}else t.applyStatus("slow",.3,.18,this.weapon);if(this.tick<=0){this.tick=.28;game.damageEnemy(t,this.s.damage*.34,{source:this.weapon,canCrit:true,knockback:8,fromX:p.x,fromY:p.y,silent:true})}if(this.life<=0)this.dead=true}
 render(g){if(!this.target||this.target.dead)return;g.save();g.strokeStyle="#f1cf59";g.lineWidth=3;g.globalAlpha=.75;g.shadowBlur=10;g.shadowColor="#eec34f";g.beginPath();g.moveTo(game.player.x,game.player.y);g.lineTo(this.target.x,this.target.y);g.stroke();g.restore()}
}
class DCBoomTube{
 constructor(x,y,color="#6de6ff",life=1.2){Object.assign(this,{x,y,color,life,max:life,dead:false})}
 update(dt){this.life-=dt;if(this.life<=0)this.dead=true}
 render(g){const k=Math.max(0,this.life/this.max);g.save();g.translate(this.x,this.y);g.globalAlpha=.35+.5*k;g.strokeStyle=this.color;g.lineWidth=3;g.shadowBlur=14;g.shadowColor=this.color;g.beginPath();g.ellipse(0,0,15,29,0,0,Math.PI*2);g.stroke();g.restore()}
}

