Game.prototype.damageEnemy=function(e,amount,o={}){const wasDead=!!e?.dead,r=DC_DAMAGE_BASE.call(this,e,amount,o),sid=o?.source?.id;if(e&&sid==="trident_atlantis"&&!e.dead){e.vsxAtlanteanMark=(e.vsxAtlanteanMark||0)+1;if(e.vsxAtlanteanMark>=2){e.vsxAtlanteanMark=0;this.explosion(e.x,e.y,82,26*this.player.damageMultiplier,"#59e1d0",62,dcSource("atlantean_mark",["water","area"]),false);this.texts.push(new FloatingText(e.x,e.y-e.size-12,"ATLANTEAN MARK","#8ff7e8",10))}}if(!wasDead&&e?.dead&&this.vsxDCUlt?.id==="azarath_metrion_zinthos")this.vsxDCUlt.souls=Math.min(80,(this.vsxDCUlt.souls||0)+1);return r};

const DC_TAKE_BASE=Player.prototype.takeDamage;
