const DC_ULT_IDS=new Set(Object.keys(DC_ULT));
const DC_ULT_BASE=Game.prototype.useUltimate;
Game.prototype.useUltimate=function(){const id=CHARACTER_DEFINITIONS[this.characterId]?.ultimate;if(!DC_ULT_IDS.has(id))return DC_ULT_BASE.apply(this,arguments);if(this.state!=="PLAYING"||this.ultimateCharge<100||this.ultimateActive)return;if(id==="contingency_protocol")return dcStartUlt(this,id,10,{scan:0});if(id==="world_of_cardboard")return dcStartUlt(this,id,8,{hit:new Map()});if(id==="amazonian_judgment")return dcStartUlt(this,id,9,{angle:0,slash:0});if(id==="infinite_mass_punch")return dcStartUlt(this,id,6,{dist:0,lx:this.player.x,ly:this.player.y});if(id==="emerald_overdrive")return dcStartUlt(this,id,10,{construct:0});if(id==="king_seven_seas")return dcStartUlt(this,id,9,{lane:0,n:0});if(id==="boom_tube_network")return dcStartUlt(this,id,10,{tube:0,shot:0});if(id==="azarath_metrion_zinthos")return dcStartUlt(this,id,10,{souls:0,pulse:0});if(id==="fate_decree")return dcStartUlt(this,id,9,{phase:-1,burst:0});if(id==="one_shot_one_city"){dcStartUlt(this,id,2.7,{done:false});const p=this.player,src=dcSource("ultimate_one_shot_one_city",["ultimate","projectile"]),targets=this.enemies.filter(e=>!e.dead&&!e.isCaptive).sort((a,b)=>(Number(b.isBoss)-Number(a.isBoss))||(Number(b.isMiniBoss)-Number(a.isMiniBoss))||(Number(b.elite)-Number(a.elite))||b.damage-a.damage).slice(0,8);targets.forEach((e,i)=>this.effects.push(new PulseDelayEffect(.15+i*.18,()=>{if(e.dead)return;const mode=i%5;if(mode===0)this.damageEnemy(e,65*p.damageMultiplier,{source:src,canCrit:true,knockback:40});else if(mode===1)this.explosion(e.x,e.y,75,52*p.damageMultiplier,"#ffc46b",60,src,false);else if(mode===2){e.applyStatus("slow",2,.55,src);this.damageEnemy(e,40*p.damageMultiplier,{source:src,canCrit:true})}else if(mode===3){e.applyStatus("shock",1.5,.2,src);this.damageEnemy(e,46*p.damageMultiplier,{source:src,canCrit:true,damageType:"electric"})}else{this.damageEnemy(e,48*p.damageMultiplier,{source:src,canCrit:true});if(!e.isBoss&&!e.isMiniBoss){const n=normalize(p.x-e.x,p.y-e.y);e.x+=n.x*55;e.y+=n.y*55}}})));this.effects.push(new PulseDelayEffect(2.0,()=>{let prev={x:p.x,y:p.y};for(const e of targets.filter(x=>!x.dead)){this.beams.push({x1:prev.x,y1:prev.y,x2:e.x,y2:e.y,life:.32,color:"#71e298",width:4});this.damageEnemy(e,54*p.damageMultiplier,{source:src,canCrit:true,damageType:"electric"});prev=e}this.texts.push(new FloatingText(p.x,p.y-50,"ONE SHOT, ONE CITY","#9ef0b3",14))}));return}
};

