Game.prototype.vsxInitRun=function(){const r=DC_INIT_BASE.apply(this,arguments);this.vsxDCUlt=null;this.vsxDCDarkness=0;this.vsxDCMoveHistory=[];this.vsxDCMoveSample=0;return r};
const DC_UPDATE_BASE=Game.prototype.update;
Game.prototype.update=function(dt){const out=DC_UPDATE_BASE.call(this,dt);if(this.vsxDCUlt&&this.state==="GAME_OVER"){this.vsxDCUlt=null;this.ultimateActive=false;this.player?.recalc?.();return out}if(this.state!=="PLAYING"||!this.player)return out;const edt=dt*(typeof VSX_ADMIN!=="undefined"?(VSX_ADMIN.speed||1):1),p=this.player;this.vsxDCMoveHistory||=[];this.vsxDCMoveSample=(this.vsxDCMoveSample||0)-edt;if(this.vsxDCMoveSample<=0){this.vsxDCMoveSample=.10;this.vsxDCMoveHistory.push({x:p.x,y:p.y,t:this.time});while(this.vsxDCMoveHistory.length&&this.time-this.vsxDCMoveHistory[0].t>5)this.vsxDCMoveHistory.shift()}const u=this.vsxDCUlt;if(!u)return out;u.time-=edt;u.tick=(u.tick||0)-edt;const src=dcSource("ultimate_"+u.id,["ultimate"]);
 if(u.id==="contingency_protocol"&&u.tick<=0){u.tick=.72;const q=dcThreat();if(q.bullets>=7){let n=0;for(const b of this.enemyProjectiles)if(!b.dead&&Math.hypot(b.x-p.x,b.y-p.y)<360&&n++<18)b.dead=true;this.effects.push(new WaveEffect(p.x,p.y,360,.45,28*p.damageMultiplier,25,src,"#84ddff"));this.texts.push(new FloatingText(p.x,p.y-42,"EMP","#9be9ff",11))}else if(q.boss){dcLine(p.x,p.y,q.boss.x,q.boss.y,7,54*p.damageMultiplier,src,"#e3c56a",{knockback:20});q.boss.applyStatus("vulnerable",.8,.06,src)}else if(q.swarm>=9){const t=this.findCluster(p.x,p.y,620)||q.near[0];if(t)this.explosion(t.x,t.y,95,48*p.damageMultiplier,"#e3b95a",80,src,false)}else{const t=q.near[0];if(t)this.effects.push(new AreaEffect({x:t.x,y:t.y,radius:95,life:1.5,damage:18*p.damageMultiplier,tick:.4,color:"rgba(90,105,120,.22)",weapon:src,status:{type:"confuse",duration:.6,strength:.25}}))}}
 else if(u.id==="world_of_cardboard"){for(const e of this.grid.queryCircle(p.x,p.y,58)){if(e.dead||e.isCaptive)continue;const ready=u.hit.get(e.id)||0;if(ready>this.time)continue;u.hit.set(e.id,this.time+.28);this.damageEnemy(e,26*p.damageMultiplier,{source:src,canCrit:true,knockback:125,fromX:p.x,fromY:p.y,silent:true})}}
 else if(u.id==="amazonian_judgment"){u.angle+=edt*2.4;u.slash-=edt;const r=215;for(const e of this.grid.queryCircle(p.x,p.y,r+45)){if(e.dead||e.isCaptive)continue;const d=Math.hypot(e.x-p.x,e.y-p.y);if(Math.abs(d-r)<e.size+18){this.damageEnemy(e,18*p.damageMultiplier,{source:src,canCrit:true,knockback:22,fromX:p.x,fromY:p.y,silent:true});if(!e.isBoss&&!e.isMiniBoss){const n=normalize(p.x-e.x,p.y-e.y);e.x+=n.x*28*edt*5;e.y+=n.y*28*edt*5}}}if(u.slash<=0){u.slash=.72;for(const off of [0,Math.PI/2])dcLine(p.x-Math.cos(u.angle+off)*330,p.y-Math.sin(u.angle+off)*330,p.x+Math.cos(u.angle+off)*330,p.y+Math.sin(u.angle+off)*330,8,40*p.damageMultiplier,src,"#f0cf62",{knockback:65})}}
 else if(u.id==="infinite_mass_punch"){const d=Math.hypot(p.x-u.lx,p.y-u.ly);u.lx=p.x;u.ly=p.y;u.dist+=d;if(u.tick<=0){u.tick=.22;this.effects.push(new WaveEffect(p.x,p.y,90,.28,18*p.damageMultiplier,55,src,"#ffe052"))}}
 else if(u.id==="emerald_overdrive"&&u.tick<=0){u.tick=.38;const q=dcThreat();for(const b of this.enemyProjectiles)if(!b.dead&&Math.hypot(b.x-p.x,b.y-p.y)<135&&Math.random()<.72)b.dead=true;if(q.boss)dcLine(p.x,p.y,q.boss.x,q.boss.y,8,38*p.damageMultiplier,src,"#6dffab",{knockback:18});if(q.swarm>=6)this.effects.push(new WaveEffect(p.x,p.y,155,.36,26*p.damageMultiplier,75,src,"#64f3a0"));const ts=this.nearestList(p.x,p.y,760,3);for(const t of ts){const n=normalize(t.x-p.x,t.y-p.y);this.projectiles.push(new Projectile({x:p.x,y:p.y,vx:n.x*620,vy:n.y*620,radius:5,damage:21*p.damageMultiplier,life:1.4,pierce:2,color:"#6af4a1",weapon:src}))}}
 else if(u.id==="king_seven_seas"&&u.tick<=0){u.tick=1.05;u.n++;const axis=u.n%3,off=((u.n%5)-2)*85;if(axis===0)dcLine(p.x-560,p.y+off,p.x+560,p.y+off,28,45*p.damageMultiplier,src,"#58ddd4",{knockback:95});else if(axis===1)dcLine(p.x+off,p.y-460,p.x+off,p.y+460,28,45*p.damageMultiplier,src,"#58ddd4",{knockback:95});else dcLine(p.x-480,p.y-360,p.x+480,p.y+360,28,45*p.damageMultiplier,src,"#58ddd4",{knockback:95})}
 else if(u.id==="boom_tube_network"){u.tube-=edt;u.shot-=edt;const nodes=[];for(let i=0;i<4;i++){const a=this.time*.42+i*Math.PI/2,n={x:p.x+Math.cos(a)*180,y:p.y+Math.sin(a)*180};nodes.push(n)}if(u.tube<=0){u.tube=.75;for(const n of nodes)this.effects.push(new DCBoomTube(n.x,n.y,"#67dfff",.82));for(const e of this.enemies){if(e.dead||e.isBoss||e.isMiniBoss||e.isCaptive)continue;for(let i=0;i<nodes.length;i++)if(Math.hypot(e.x-nodes[i].x,e.y-nodes[i].y)<28){const q=nodes[(i+2)%4];e.x=q.x;e.y=q.y;break}}for(const b of this.enemyProjectiles)if(!b.dead&&nodes.some(n=>Math.hypot(b.x-n.x,b.y-n.y)<30))b.dead=true}if(u.shot<=0){u.shot=.26;const t=dcStrongest(900)||this.findNearest(p.x,p.y,900);if(t)for(const n0 of nodes.slice(0,2)){const n=normalize(t.x-n0.x,t.y-n0.y);this.projectiles.push(new Projectile({x:n0.x,y:n0.y,vx:n.x*680,vy:n.y*680,radius:5,damage:22*p.damageMultiplier,life:1.4,pierce:2,color:"#79e7ff",weapon:src}))}}}
 else if(u.id==="azarath_metrion_zinthos"){u.pulse-=edt;if(u.pulse<=0){u.pulse=.55;const scale=1+Math.min(1.6,(u.souls||0)/25);this.effects.push(new WaveEffect(p.x,p.y,180+Math.min(160,(u.souls||0)*3),.45,22*p.damageMultiplier*scale,45,src,"#8b62c4"));this.texts.push(new FloatingText(p.x,p.y-42,`SOUL ${u.souls||0}`,"#bc92ef",9))}}
 else if(u.id==="fate_decree"){const elapsed=u.max-u.time,phase=Math.min(2,Math.floor(elapsed/3));if(phase!==u.phase){u.phase=phase;this.texts.push(new FloatingText(p.x,p.y-48,["STILLNESS","ORDER","RUIN"][phase],"#f4d77a",13))}if(phase===0){const f=Math.pow(.35,edt);for(const b of this.enemyProjectiles)if(!b.dead){b.vx*=f;b.vy*=f}}else if(phase===1){for(const e of this.grid.queryCircle(p.x,p.y,500)){if(e.dead||e.isBoss||e.isMiniBoss||e.isCaptive)continue;const tx=Math.round(e.x/110)*110,ty=Math.round(e.y/110)*110;e.x=lerp(e.x,tx,clamp(edt*1.8,0,1));e.y=lerp(e.y,ty,clamp(edt*1.8,0,1));e.applyStatus("slow",.25,.18,src)}}else{u.burst-=edt;if(u.burst<=0){u.burst=.55;const t=this.findCluster(p.x,p.y,680)||dcStrongest(680);if(t)this.explosion(t.x,t.y,105,42*p.damageMultiplier,"#e5c35c",65,src,false)}}}
 if(u.time<=0)dcFinishUlt(this);return out};

/* =========================================================
   SAVE / PURCHASE / PACKAGE
   ========================================================= */
function dcEnsureSave(){ensureArmorySave();VSX.save.meta.packages||={};VSX.save.meta.packageEffects||={};VSX.save.meta.skins||={};VSX.save.meta.unlockedCharacters||={};VSX.save.meta.unlockedWeapons||={};if(VSX.save.meta.packageEffects[DC_PACKAGE_ID]===undefined)VSX.save.meta.packageEffects[DC_PACKAGE_ID]=false;dcSyncCompletion(false)}
function dcOwned(id){return !!VSX.save.meta.unlockedCharacters?.[id]}
function dcPackageOwned(){return !!VSX.save.meta.packages?.[DC_PACKAGE_ID]}
function dcGrant(id,announce=false){const o=DC_CONTENT[id],d=CHARACTER_DEFINITIONS[id];if(!o||!d)return false;VSX.save.meta.unlockedCharacters[id]=true;VSX.save.meta.unlockedWeapons[o.weapon]=true;VSX.save.meta.skins[o.skin]=true;vsxDiscover("characters",id);vsxDiscover("weapons",o.weapon);if(announce)VSX.announce(VSX.lang==="vi"?"ĐÃ MỞ KHÓA DC HERO":"DC HERO UNLOCKED",d.name[VSX.lang],o.color);return true}
function dcSyncCompletion(save=true){if(DC_IDS.every(dcOwned)){for(const id of DC_IDS)dcGrant(id,false);VSX.save.meta.packages[DC_PACKAGE_ID]=true;if(save)vsxSave();return true}return false}
function dcBundlePrice(){const missing=DC_IDS.filter(id=>!dcOwned(id));if(!missing.length)return 0;return Math.ceil((missing.reduce((s,id)=>s+DC_CONTENT[id].cost,0)*.85)/500)*500}
function dcBuyOne(id){dcEnsureSave();if(dcOwned(id))return true;const o=DC_CONTENT[id];if(!walletSpend("score",o.cost))return false;dcGrant(id,true);dcSyncCompletion(false);vsxSave();return true}
function dcBuyBundle(){dcEnsureSave();if(dcPackageOwned())return true;const price=dcBundlePrice();if(price&&!walletSpend("score",price))return false;for(const id of DC_IDS)dcGrant(id,false);VSX.save.meta.packages[DC_PACKAGE_ID]=true;VSX.save.meta.packageEffects[DC_PACKAGE_ID]=false;vsxSave();VSX.announce(VSX.lang==="vi"?"DC HEROES — CRISIS PROTOCOL HOÀN TẤT":"DC HEROES — CRISIS PROTOCOL COMPLETE","WATCHTOWER GRID + CRISIS TRAIL","#72ddff");return true}
function dcEffectOn(){return dcPackageOwned()&&VSX.save.meta.packageEffects?.[DC_PACKAGE_ID]!==false}
function dcEquipSkin(id,save=false){const o=DC_CONTENT[id];if(!o||!VSX.save.meta.skins?.[o.skin])return false;if(VSX.save.loadout.skin!==o.skin){VSX.save.loadout.skin=o.skin;if(save)vsxSave()}return true}

function dcUltInfo(id){return DC_ULT[id]||window.VSX_EPIC6_EXPANSION?.ultInfo?.(id)||window.VSX_ARCADE_EXPANSION?.ultInfo?.(id)||{name:{en:id.replaceAll("_"," ").toUpperCase(),vi:id.replaceAll("_"," ").toUpperCase()},how:{en:"Activates this survivor's unique Ultimate.",vi:"Kích hoạt Tuyệt Kỹ riêng của nhân vật này."}}}
function dcShopCard(id){const m=DC_CONTENT[id],d=CHARACTER_DEFINITIONS[id],u=DC_ULT[d.ultimate],owned=dcOwned(id),card=document.createElement("article");card.dataset.dcCard=id;card.className=`vsxShopCard vsxSurvivorShopCard vsxUnifiedSurvivorCard ${m.rarity}${owned?" owned":""}`;card.style.setProperty("--surv-color",m.color);const price=owned?t("owned"):m.cost.toLocaleString("en-US")+" "+t("spendScore");card.innerHTML=`<div class="vsxUnifiedSurvivorHead"><span class="vsxRarityBadge ${m.rarity}">${m.rarity.toUpperCase()}</span><span class="vsxShopOwnedChip ${owned?"owned":""}">${owned?(VSX.lang==="vi"?"SỞ HỮU":"OWNED"):(VSX.lang==="vi"?"CHƯA SỞ HỮU":"LOCKED")}</span></div><h3>${VSX.esc(d.name[VSX.lang])}<span class="vsxDCBadge">DC HEROES</span></h3><p class="vsxUnifiedSurvivorDesc">${VSX.esc(d.desc[VSX.lang])}</p><div class="vsxSurvivorMeta vsxUnifiedSurvivorMeta"><span><b>${VSX.lang==="vi"?"Vũ khí":"Weapon"}:</b> ${VSX.esc(weaponName(d.weapon))}</span><span><b>${VSX.lang==="vi"?"Tuyệt Kỹ":"Ultimate"}:</b> ${VSX.esc(u.name[VSX.lang])}</span><span><b>Skin:</b> ${VSX.esc(SKIN_DEFINITIONS[m.skin].name[VSX.lang])}</span></div><div class="vsxUnifiedSurvivorFooter"><p class="vsxPrice">${VSX.esc(price)}</p><button ${owned||!walletCan("score",m.cost)?"disabled":""}>${owned?t("owned"):t("buy")}</button></div>`;card.querySelector("button").onclick=()=>{if(dcBuyOne(id))renderArmory()};return card}
function dcEnhanceSurvivorShop(){if(ARMORY_TAB!=="survivors")return;const root=document.getElementById("vsxUnifiedSurvivorShop");if(!root)return;root.querySelectorAll("[data-dc-card]").forEach(x=>x.remove());for(const id of DC_IDS){const rarity=DC_CONTENT[id].rarity,grid=root.querySelector(`.vsxRarityBlock.${rarity} .vsxUnifiedSurvivorGrid`);if(grid)grid.appendChild(dcShopCard(id))}for(const rarity of ["rare","epic","legendary"]){const block=root.querySelector(`.vsxRarityBlock.${rarity}`),grid=block?.querySelector(".vsxUnifiedSurvivorGrid");if(block&&grid){const n=grid.children.length,last=block.querySelector(".vsxRarityHeader>span");if(last)last.textContent=`${n} ${VSX.lang==="vi"?"NHÂN VẬT":"SURVIVORS"}`;const sum=root.querySelector(`.vsxShopRaritySummary .${rarity}`);if(sum)sum.textContent=`${rarity.toUpperCase()} · ${n}`}}const total=root.querySelectorAll(".vsxUnifiedSurvivorCard").length,intro=root.querySelector(".vsxUnifiedShopIntro");if(intro)intro.textContent=VSX.lang==="vi"?`${total} nhân vật cửa hàng dùng chung một layout và được sắp theo độ hiếm. DC Heroes cũng tuân theo cùng hệ card, rarity và cơ chế mở signature weapon.`:`${total} shop survivors share one layout and remain sorted by rarity. DC Heroes use the same card, rarity and signature-weapon unlock system.`}
function dcAppendPackageShop(){if(ARMORY_TAB!=="packages")return;dcEnsureSave();const c=document.getElementById("vsxArmoryContent");if(!c||document.getElementById("vsxDCPackage"))return;const owned=DC_IDS.filter(dcOwned).length,price=dcBundlePrice(),pack=dcPackageOwned(),fx=dcEffectOn(),sec=document.createElement("section");sec.id="vsxDCPackage";sec.className="vsxDCPackage";sec.innerHTML=`<div class="vsxDCPackageHead"><div><div class="vsxDCKicker">DC HEROES · CRISIS PROTOCOL</div><h3>JUSTICE · MAGIC · TECH</h3><p>${VSX.lang==="vi"?"10 anh hùng · 10 signature weapon · 10 orb skin độc quyền. Năm Legendary dẫn đầu bundle; năm Epic bổ sung các lối chơi thủy triều, portal, soul banking, rune sequencing và trick-arrow.":"10 heroes · 10 signature weapons · 10 exclusive orb skins. Five Legendary heroes anchor the bundle; five Epic heroes add tidal, portal, soul-banking, rune-sequencing and trick-arrow playstyles."}</p></div><div class="vsxDCPackagePrice"><small>${pack?(VSX.lang==="vi"?"TRẠNG THÁI":"STATUS"):(VSX.lang==="vi"?"GIÁ GÓI HIỆN TẠI":"CURRENT BUNDLE PRICE")}</small><b>${pack?(VSX.lang==="vi"?"ĐÃ SỞ HỮU":"OWNED"):price.toLocaleString("en-US")+" SCORE"}</b><span>${owned}/10 ${VSX.lang==="vi"?"NHÂN VẬT":"SURVIVORS"}</span></div></div><div class="vsxDCRoster">${DC_IDS.map(id=>{const o=DC_CONTENT[id],d=CHARACTER_DEFINITIONS[id];return `<div class="vsxDCRosterCard ${dcOwned(id)?"owned":""}"><span class="vsxRarityBadge ${o.rarity}">${o.rarity.toUpperCase()}</span><b>${VSX.esc(d.name[VSX.lang])}</b><small>${VSX.esc(weaponName(o.weapon))}<br>${dcOwned(id)?(VSX.lang==="vi"?"ĐÃ SỞ HỮU":"OWNED"):(VSX.lang==="vi"?"MUA LẺ TRONG NHÂN VẬT":"INDIVIDUAL IN SURVIVORS")}</small></div>`}).join("")}</div><div class="vsxDCPackageActions"><button id="vsxBuyDCBundle" ${pack||!walletCan("score",price)?"disabled":""}>${pack?(VSX.lang==="vi"?"ĐÃ SỞ HỮU TRỌN GÓI":"PACKAGE OWNED"):(VSX.lang==="vi"?"MUA TRỌN GÓI":"BUY BUNDLE")+` · ${price.toLocaleString("en-US")}`}</button><button id="vsxDCEffectToggle" ${pack?"":"disabled"}>WATCHTOWER GRID + CRISIS TRAIL: ${fx?"ON":"OFF"}</button></div><div class="vsxDCBonus"><b>${VSX.lang==="vi"?"THƯỞNG TRỌN BỘ":"FULL SET BONUS"}</b> · WATCHTOWER GRID + CRISIS TRAIL — ${VSX.lang==="vi"?"hiệu ứng nền và trail thuần mỹ thuật; không cộng chỉ số.":"cosmetic battlefield ambience and movement trail only; no gameplay stats."}</div>`;c.appendChild(sec);sec.querySelector("#vsxBuyDCBundle").onclick=()=>{if(dcBuyBundle())renderArmory()};sec.querySelector("#vsxDCEffectToggle").onclick=()=>{VSX.save.meta.packageEffects[DC_PACKAGE_ID]=!dcEffectOn();vsxSave();renderArmory()}}

const DC_ARMORY_BASE=renderArmory;
renderArmory=function(){const r=DC_ARMORY_BASE.apply(this,arguments);if(ARMORY_TAB==="survivors")dcEnhanceSurvivorShop();if(ARMORY_TAB==="packages")dcAppendPackageShop();return r};

/* Generic package-aware skin shop; fixes old Football-only labels and remains future-proof. */
function dcSkinPackageLabel(d){if(d.packageId===DC_PACKAGE_ID||DC_IDS.includes(d.characterOnly))return "DC HEROES — CRISIS PROTOCOL";if(["ronaldo_r9","pele_p10","ronaldinho_r10"].includes(d.characterOnly))return "FOOTBALL LEGENDS VOL. 1";return VSX.lang==="vi"?"GÓI NHÂN VẬT":"PACKAGE"}
const DC_RENDER_CUSTOM_BASE=renderCustomization;
renderCustomization=function(c){dcEnsureSave();c.innerHTML=`<div class="vsxSectionTitle">${t("skins")}</div><p style="font-size:11px;color:#8098b0;margin:0 0 10px">${VSX.lang==="vi"?"Ngoại trang chỉ thay đổi hình ảnh. Skin độc quyền nhân vật chỉ trang bị được cho đúng survivor.":"Skins are cosmetic only. Character-exclusive skins can only be equipped by their matching survivor."}</p><div class="vsxShopGrid" id="vsxSkinGrid"></div>`;const g=document.getElementById("vsxSkinGrid");for(const [id,d] of Object.entries(SKIN_DEFINITIONS)){const own=!!VSX.save.meta.skins[id],sel=VSX.save.loadout.skin===id,compat=!d.characterOnly||d.characterOnly===VSX.selectedCharacter,exclusive=!!d.packageExclusive,effect=d.effect||(VSX.lang==="vi"?"Màu nhân vật":"Character color"),pkg=exclusive?dcSkinPackageLabel(d):"",extra=`<div class="vsxSkinPreview" style="--skin:${d.color}"><i></i></div><p style="font-size:10px;color:#9bb2c6">${VSX.lang==="vi"?"Hiệu ứng":"Effect"}: <b>${VSX.esc(effect)}</b></p>${d.characterOnly?`<p style="font-size:9px;color:#f5d56c">${VSX.lang==="vi"?"ĐỘC QUYỀN":"EXCLUSIVE"}: ${VSX.esc(CHARACTER_DEFINITIONS[d.characterOnly]?.name?.[VSX.lang]||d.characterOnly)}</p>`:""}<p class="vsxPrice">${own?t("owned"):exclusive?VSX.esc(pkg):d.cost+" "+(d.currency==="score"?t("spendScore"):t("spendKills"))}</p>`;const label=sel?t("equipped"):own?(compat?(VSX.lang==="vi"?"TRANG BỊ":"EQUIP"):(VSX.lang==="vi"?"SAI NHÂN VẬT":"WRONG SURVIVOR")):exclusive?(VSX.lang==="vi"?"ĐỘC QUYỀN GÓI":"PACKAGE ONLY"):t("buy"),disabled=sel||(own&&!compat)||(!own&&exclusive)||(!own&&!exclusive&&!walletCan(d.currency,d.cost));g.appendChild(shopCard(d.name[VSX.lang],VSX.lang==="vi"?"Ngoại trang và hiệu ứng thuần mỹ thuật.":"Cosmetic skin and visual effect only.",extra,label,disabled,()=>{if(!own){if(exclusive||!walletSpend(d.currency,d.cost))return;VSX.save.meta.skins[id]=true}if(d.characterOnly&&d.characterOnly!==VSX.selectedCharacter)return;VSX.save.loadout.skin=id;vsxSave();renderArmory()},d.tier?`skin${d.tier[0].toUpperCase()+d.tier.slice(1)}`:""))}};

/* Collection sync. */
const DC_CODEX_ENTRIES_BASE=VSX.codexEntries;
VSX.codexEntries=function(cat){const rows=DC_CODEX_ENTRIES_BASE.call(VSX,cat);if(cat==="packages")return [...rows,[DC_PACKAGE_ID,"DC HEROES — CRISIS PROTOCOL",VSX.lang==="vi"?"10 anh hùng DC với signature weapon, orb skin độc quyền và hiệu ứng trọn bộ.":"10 DC heroes with signature weapons, exclusive orb skins and full-set cosmetics."]];return rows};
const DC_SHOW_COLLECTION_BASE=VSX.showCollection;
VSX.showCollection=function(){const r=DC_SHOW_COLLECTION_BASE.apply(this,arguments),b=document.getElementById("vsxPackageCodexTab");if(b){const owned=[window.VSX_FOOTBALL_PACKAGE?.owned?.(),dcPackageOwned()].filter(Boolean).length;b.textContent=`${VSX.lang==="vi"?"GÓI NHÂN VẬT":"PACKAGES"} ${owned}/2`}return r};
const DC_CODEX_RENDER_BASE=VSX.renderCodex;
VSX.renderCodex=function(cat){dcEnsureSave();if(cat==="packages"){DC_CODEX_RENDER_BASE.call(VSX,cat);const list=document.getElementById("vsxCodexList");if(!list)return;const e=document.createElement("div");e.className="vsxCodexItem";e.innerHTML=`<div><b>DC HEROES — CRISIS PROTOCOL</b><span class="vsxDCBadge">${dcPackageOwned()?(VSX.lang==="vi"?"ĐÃ SỞ HỮU":"OWNED"):(VSX.lang==="vi"?"CHƯA HOÀN TẤT":"INCOMPLETE")}</span></div><div style="margin-top:6px">${DC_IDS.map(id=>VSX.esc(CHARACTER_DEFINITIONS[id].name[VSX.lang])).join(" · ")}</div><div class="vsxPkgCollection">${DC_IDS.map(id=>`<div><small>${VSX.esc(CHARACTER_DEFINITIONS[id].name[VSX.lang])}</small><b>${VSX.esc(weaponName(DC_CONTENT[id].weapon))}</b><small>${VSX.esc(SKIN_DEFINITIONS[DC_CONTENT[id].skin].name[VSX.lang])}</small></div>`).join("")}</div>`;list.appendChild(e);return}if(cat==="characters"){const list=document.getElementById("vsxCodexList");if(!list)return;list.innerHTML="";for(const [id,n,dsc] of VSX.codexEntries("characters")){const d=CHARACTER_DEFINITIONS[id],owned=isCharacterUnlocked(id),u=dcUltInfo(d.ultimate),rarity=d.rarity||"common",e=document.createElement("div");e.className="vsxCodexItem vsxCharacterCodexCard";const badge=d.packageId===DC_PACKAGE_ID?'<span class="vsxDCBadge">DC HEROES</span>':d.packageId?'<span class="vsxFootballBadge">FOOTBALL LEGENDS</span>':"";e.innerHTML=`<div class="vsxCharacterCodexHead"><b>${VSX.esc(n)}</b><span class="vsxRarityBadge ${rarity}">${rarity.toUpperCase()}</span>${badge}</div><div>${VSX.esc(dsc)}</div><div class="vsxCharacterCodexDetail"><div><b>${VSX.lang==="vi"?"Vũ khí":"Weapon"}:</b> ${VSX.esc(weaponName(d.weapon))}</div><div><b>${VSX.lang==="vi"?"Tuyệt Kỹ":"Ultimate"}:</b> ${VSX.esc(u.name[VSX.lang])}</div><div class="vsxUltHow"><b>${VSX.lang==="vi"?"Cách Tuyệt Kỹ thể hiện":"How the Ultimate works"}:</b> ${VSX.esc(u.how[VSX.lang])}</div></div><div class="vsxCharacterOwned ${owned?"owned":"locked"}">${owned?(VSX.lang==="vi"?"SỞ HỮU":"OWNED"):(d.shopOnly?(VSX.lang==="vi"?"KHÓA TRONG CỬA HÀNG":"SHOP LOCKED"):(VSX.lang==="vi"?"CHƯA MỞ KHÓA":"LOCKED"))}</div>`;list.appendChild(e)}return}if(cat==="skins"){const list=document.getElementById("vsxCodexList");if(!list)return;list.innerHTML="";for(const [id,d] of Object.entries(SKIN_DEFINITIONS)){const owned=!!VSX.save.meta.skins?.[id],e=document.createElement("div"),pkg=d.packageExclusive?dcSkinPackageLabel(d):"";e.className="vsxCodexItem";e.innerHTML=`<b>${VSX.esc(d.name[VSX.lang])}</b>${pkg?`<span class="${d.packageId===DC_PACKAGE_ID||DC_IDS.includes(d.characterOnly)?"vsxDCBadge":"vsxFootballBadge"}">${VSX.esc(pkg)}</span>`:""}<div class="vsxSkinCollectionSwatch" style="--skin:${d.color}"></div><div>${VSX.lang==="vi"?"Hiệu ứng":"Effect"}: ${VSX.esc(d.effect||"")}</div><div style="margin-top:6px;font-size:9px;color:${owned?'#73eeb8':'#ffbd76'}">${owned?(VSX.lang==='vi'?'SỞ HỮU':'OWNED'):(VSX.lang==='vi'?'CHƯA MỞ KHÓA':'LOCKED')}</div>`;list.appendChild(e)}return}return DC_CODEX_RENDER_BASE.call(VSX,cat)};

/* Character skin auto-equip + minimal orb symbols. */
const DC_SETUP_BASE=VSX.renderSetup;
VSX.renderSetup=function(){dcEquipSkin(VSX.selectedCharacter,false);return DC_SETUP_BASE.apply(this,arguments)};
const DC_BEGIN_BASE=VSX.beginRun;
VSX.beginRun=function(){dcEquipSkin(VSX.selectedCharacter,true);return DC_BEGIN_BASE.apply(this,arguments)};
const DC_PLAYER_RENDER_BASE=Player.prototype.render;
Player.prototype.render=function(g){DC_PLAYER_RENDER_BASE.call(this,g);const id=game?.characterId||VSX.selectedCharacter,o=DC_CONTENT[id],sid=VSX.save?.loadout?.skin;if(!o||sid!==o.skin)return;const r=this.radius,t=game.time||0;g.save();g.translate(this.x,this.y);g.globalAlpha=.96;g.lineWidth=2.3;g.strokeStyle=SKIN_DEFINITIONS[sid].secondary||"#fff";g.shadowBlur=8;g.shadowColor=g.strokeStyle;if(id==="batman"){g.fillStyle="#111318";g.beginPath();g.moveTo(-11,1);g.lineTo(-7,-5);g.lineTo(-2,-2);g.lineTo(0,-7);g.lineTo(2,-2);g.lineTo(7,-5);g.lineTo(11,1);g.lineTo(5,0);g.lineTo(0,6);g.lineTo(-5,0);g.closePath();g.fill()}else if(id==="superman"){g.strokeStyle="#e4c04d";g.beginPath();g.moveTo(0,-10);g.lineTo(10,-3);g.lineTo(6,9);g.lineTo(-6,9);g.lineTo(-10,-3);g.closePath();g.stroke();g.fillStyle="#f1d25b";g.font="900 10px Arial";g.textAlign="center";g.textBaseline="middle";g.fillText("S",0,1)}else if(id==="wonder_woman"){g.fillStyle="#efd06b";g.font="900 10px Arial";g.textAlign="center";g.textBaseline="middle";g.fillText("W",0,1)}else if(id==="the_flash"){g.fillStyle="#f5dd49";g.beginPath();g.moveTo(2,-12);g.lineTo(-5,0);g.lineTo(1,0);g.lineTo(-3,12);g.lineTo(9,-3);g.lineTo(3,-3);g.closePath();g.fill()}else if(id==="green_lantern"){g.strokeStyle="#d7ffe7";g.lineWidth=2.5;g.beginPath();g.arc(0,0,7,0,Math.PI*2);g.stroke();g.beginPath();g.moveTo(-10,-6);g.lineTo(10,-6);g.moveTo(-10,6);g.lineTo(10,6);g.stroke()}else if(id==="aquaman"){g.strokeStyle="#e8f7db";g.beginPath();g.moveTo(0,10);g.lineTo(0,-9);g.moveTo(0,-9);g.lineTo(-6,-3);g.moveTo(0,-9);g.lineTo(6,-3);g.moveTo(-6,-3);g.lineTo(-6,-9);g.moveTo(6,-3);g.lineTo(6,-9);g.stroke()}else if(id==="cyborg"){g.fillStyle="#ef4b4b";g.beginPath();g.arc(0,0,4,0,Math.PI*2);g.fill();g.strokeStyle="#e9f1f5";g.strokeRect(-9,-9,18,18)}else if(id==="raven"){g.fillStyle="#df485a";g.rotate(Math.PI/4);g.fillRect(-4,-4,8,8)}else if(id==="doctor_fate"){g.strokeStyle="#fff0a5";g.beginPath();g.arc(0,-4,5,0,Math.PI*2);g.moveTo(0,1);g.lineTo(0,11);g.moveTo(-6,5);g.lineTo(6,5);g.stroke()}else if(id==="green_arrow"){g.strokeStyle="#d9ffe4";g.beginPath();g.moveTo(-10,7);g.lineTo(8,-7);g.moveTo(8,-7);g.lineTo(3,-6);g.moveTo(8,-7);g.lineTo(7,-2);g.stroke()}if(dcEffectOn()){const dir=game.lastMoveDir||{x:1,y:0};for(let i=1;i<=3;i++){g.globalAlpha=.14*(4-i);g.fillStyle=i===1?"#ffffff":i===2?"#69dfff":"#e7c75d";g.beginPath();g.arc(-dir.x*(r+7+i*7),-dir.y*(r+7+i*7),2.2,0,Math.PI*2);g.fill()}}g.restore()};

const DC_GAME_RENDER_BASE=Game.prototype.render;
Game.prototype.render=function(){const r=DC_GAME_RENDER_BASE.apply(this,arguments);if(!dcEffectOn()||!this.player||this.state==="TITLE")return r;ctx.save();ctx.translate(-this.camera.x,-this.camera.y);const p=this.player,step=72,rad=330;ctx.globalAlpha=.045;ctx.strokeStyle="#75dfff";ctx.lineWidth=1;for(let x=Math.floor((p.x-rad)/step)*step;x<=p.x+rad;x+=step){ctx.beginPath();ctx.moveTo(x,p.y-rad);ctx.lineTo(x,p.y+rad);ctx.stroke()}for(let y=Math.floor((p.y-rad)/step)*step;y<=p.y+rad;y+=step){ctx.beginPath();ctx.moveTo(p.x-rad,y);ctx.lineTo(p.x+rad,y);ctx.stroke()}ctx.restore();return r};

/* Admin QA card. */
function dcAdminL(en,vi){return VSX.lang==="vi"?vi:en}
function dcInjectAdmin(){const grid=document.querySelector("#vsxAdminContent .vsxAdminGrid");if(!grid||document.getElementById("vsxAdminDCHeroesCard")||!["meta","loadout","collection","player"].includes(VSX_ADMIN?.tab))return;const card=document.createElement("div");card.id="vsxAdminDCHeroesCard";card.className="vsxAdminCard";card.innerHTML=`<h3>DC HEROES · CRISIS PROTOCOL QA</h3><p>${dcAdminL("Unlock, select, grant signature weapons, equip skins and live-test all ten DC Ultimates.","Mở khóa, chọn, cấp signature weapon, trang bị skin và test trực tiếp cả 10 Tuyệt Kỹ DC.")}</p><select id="admDCHero">${DC_IDS.map(id=>`<option value="${id}">${VSX.esc(CHARACTER_DEFINITIONS[id].name[VSX.lang])} · ${DC_CONTENT[id].rarity.toUpperCase()}</option>`).join("")}</select><div class="row"><button id="admDCUnlock">${dcAdminL("UNLOCK","MỞ KHÓA")}</button><button id="admDCNext">${dcAdminL("SET NEXT RUN","CHỌN TRẬN SAU")}</button><button id="admDCWeapon">${dcAdminL("ADD WEAPON","THÊM VŨ KHÍ")}</button><button id="admDCUlt">${dcAdminL("LIVE TEST ULT","TEST ULT NGAY")}</button></div><div class="row"><button id="admDCBundle">${dcAdminL("UNLOCK FULL DC PACKAGE","MỞ KHÓA TRỌN GÓI DC")}</button></div>`;grid.appendChild(card);const sel=card.querySelector("#admDCHero");card.querySelector("#admDCUnlock").onclick=()=>{dcGrant(sel.value,true);dcEquipSkin(sel.value,true);vsxSave()};card.querySelector("#admDCNext").onclick=()=>{dcGrant(sel.value,false);VSX.selectedCharacter=sel.value;dcEquipSkin(sel.value,true);vsxSave();VSX.announce("ADMIN",dcAdminL("NEXT RUN DC HERO SET","ĐÃ CHỌN DC HERO TRẬN SAU"),"#75ddff")};card.querySelector("#admDCWeapon").onclick=()=>{if(!game.player)return VSX.announce("ADMIN",dcAdminL("START A RUN FIRST","HÃY VÀO TRẬN TRƯỚC"),"#ff9b71");const id=sel.value,w=DC_CONTENT[id].weapon;dcGrant(id,false);if(!game.player.weapons.some(x=>x.id===w)){if(game.player.weapons.length>=game.player.weaponSlots)game.player.weapons.shift();game.player.addWeapon(w)}game.updateHUD(true)};card.querySelector("#admDCUlt").onclick=()=>{if(!game.player)return VSX.announce("ADMIN",dcAdminL("START A RUN FIRST","HÃY VÀO TRẬN TRƯỚC"),"#ff9b71");const id=sel.value,w=DC_CONTENT[id].weapon;dcGrant(id,false);game.characterId=id;dcEquipSkin(id,true);if(!game.player.weapons.some(x=>x.id===w)){if(game.player.weapons.length>=game.player.weaponSlots)game.player.weapons.shift();game.player.addWeapon(w)}game.vsxDCUlt=null;game.vsxEpic6Ult=null;game.vsxArcadeUlt=null;game.vsxExpansionUlt=null;game.vsxFootballUlt=null;game.ultimateBuff=null;game.ultimateBuffTimer=0;game.ultimateActive=false;game.ultimateCharge=100;game.player.recalc();game.useUltimate();game.updateHUD(true)};card.querySelector("#admDCBundle").onclick=()=>{for(const id of DC_IDS)dcGrant(id,false);VSX.save.meta.packages[DC_PACKAGE_ID]=true;VSX.save.meta.packageEffects[DC_PACKAGE_ID]=false;vsxSave();VSX.announce("ADMIN",dcAdminL("FULL DC PACKAGE UNLOCKED","ĐÃ MỞ KHÓA TRỌN GÓI DC"),"#75ddff")}}
if(window.VSX_ADMIN){const old=VSX_ADMIN.openPanel;if(typeof old==="function")VSX_ADMIN.openPanel=function(){const r=old.apply(this,arguments);queueMicrotask(dcInjectAdmin);return r};const c=document.getElementById("vsxAdminContent");if(c)new MutationObserver(()=>{if(VSX_ADMIN.open&&!document.getElementById("vsxAdminDCHeroesCard"))queueMicrotask(dcInjectAdmin)}).observe(c,{childList:true})}

